(x, y, t) => {
  const cx = 240, cy = 120;
  const w1x = Math.sin(x * 0.018 + t * 0.25) * 18 + Math.cos(y * 0.013 - t * 0.18) * 12;
  const w1y = Math.cos(y * 0.016 - t * 0.22) * 18 + Math.sin(x * 0.014 + t * 0.3) * 12;
  const w2x = Math.sin((x + w1x) * 0.025 - t * 0.4) * 8 + Math.cos((y + w1y) * 0.02 + t * 0.35) * 6;
  const w2y = Math.cos((y + w1y) * 0.022 + t * 0.38) * 8 + Math.sin((x + w1x) * 0.019 - t * 0.42) * 6;
  const sx = x + w1x + w2x, sy = y + w1y + w2y;
  const src = [
    [160+Math.sin(t*0.5)*110, 70+Math.cos(t*0.35)*55, 0.075, 2.1, 0.6],
    [320+Math.cos(t*0.45)*100, 160+Math.sin(t*0.65)*55, 0.095, 1.8, 0.8],
    [240+Math.sin(t*0.28+2)*150, 110+Math.cos(t*0.48+1)*95, 0.055, 2.4, 0.5],
    [100+Math.cos(t*0.75+1)*85, 185+Math.sin(t*0.55+3)*65, 0.11, 1.6, 0.7],
    [370+Math.sin(t*0.38+4)*95, 55+Math.cos(t*0.85+2)*75, 0.065, 2.7, 0.4],
    [240+Math.cos(t*0.32+5)*130, 210+Math.sin(t*0.52)*85, 0.085, 2.0, 0.9],
    [60+Math.sin(t*0.6+3)*70, 40+Math.cos(t*0.7+1)*45, 0.1, 1.9, 0.55],
    [420+Math.cos(t*0.42+2)*60, 200+Math.sin(t*0.58+4)*50, 0.07, 2.2, 0.65]
  ];
  let aS = 0, iS = 0, wS = 0;
  for (const [sX, sY, f, sp, wt] of src) {
    const d = Math.sqrt((sx-sX)**2 + (sy-sY)**2);
    aS += (Math.sin(d*f - t*sp) + Math.sin(d*f*1.5 - t*sp*0.7 + 1.0)) * wt;
    iS += (Math.sin(d*f*0.65 + t*sp*0.55 + 1.5) + Math.cos(d*f*0.8 - t*sp*0.4 + 2.3)) * wt;
    wS += Math.sin(d*f*0.3 + t*sp*0.3) * Math.cos(d*f*0.2 - t*sp*0.5 + 0.8) * wt;
  }
  const tw = 0.45 + 0.15 * Math.sin(t * 0.2);
  const act = aS / 5.2, inh = iS / 5.2, wav = wS / 5.2;
  const bg1 = (Math.sin(sx*0.035+sy*0.022+t*0.7) + Math.sin(sx*0.028-sy*0.038+t*1.0))/2;
  const bg2 = (Math.sin((sx+sy)*0.11+t*2.3) + Math.sin((sx-sy)*0.09-t*1.8))*0.25;
  const bg3 = Math.sin(sx*0.065+Math.sin(sy*0.05+t*0.5)*2+t*1.5)*0.15;
  const bg = bg1 + bg2 + bg3;
  const dist = Math.sqrt((sx-cx)**2 + (sy-cy)**2), ang = Math.atan2(sy-cy, sx-cx);
  const sp1 = Math.sin(dist*0.045-ang*3.5-t*1.4);
  const sp2 = Math.sin(dist*0.035+ang*4.5-t*1.1);
  const sp3 = Math.sin(dist*0.06-ang*2-t*1.8+Math.sin(ang*2+t)*0.5);
  const spiral = (sp1 + sp2 + sp3) * 0.28;
  const diffusion = Math.tanh((act - inh*tw + bg*0.25 + spiral + wav*0.3)*2.0);
  const cellA = Math.sin(sx*0.14)*Math.sin(sy*0.14);
  const cellB = Math.sin((sx+sy)*0.095+t*0.8)*Math.sin((sx-sy)*0.08-t*0.6);
  const cellC = Math.sin(sx*0.07+Math.cos(sy*0.06+t*0.4)*1.5)*Math.sin(sy*0.11+Math.sin(sx*0.05-t*0.3)*1.5);
  const cell = Math.tanh((cellA + cellB*0.7 + cellC*0.5)*1.6)*0.25;
  const pulse = 0.05 * Math.sin(t*1.2 + dist*0.03) * Math.exp(-dist*0.005);
  const blend = diffusion*0.7 + cell*0.25 + pulse;
  const v = blend*0.5+0.5;
  const pal = [
    [6, 12, 52], [12, 45, 85], [18, 82, 108], [25, 128, 128],
    [65, 165, 130], [150, 190, 95], [210, 195, 70], [225, 155, 65],
    [210, 105, 60], [185, 65, 55], [140, 40, 55], [85, 22, 52], [6, 12, 52]
  ];
  const idx = v*(pal.length-1), i = Math.min(idx|0, pal.length-2), f = idx-i;
  const sf = f*f*(3-2*f);
  const lum = 0.82 + Math.sin(Math.abs(diffusion)*Math.PI)*0.18;
  const edge = Math.abs(diffusion)>0.65 ? 1.12 + Math.abs(diffusion)*0.08 : 0.95 + Math.abs(blend)*0.05;
  const glow = Math.max(0, 1 - Math.abs(diffusion)*1.5)*0.15;
  return [
    Math.min(255, ((pal[i][0]+(pal[i+1][0]-pal[i][0])*sf)*lum*edge + glow*40)|0),
    Math.min(255, ((pal[i][1]+(pal[i+1][1]-pal[i][1])*sf)*lum*edge + glow*30)|0),
    Math.min(255, ((pal[i][2]+(pal[i+1][2]-pal[i][2])*sf)*lum*edge + glow*50)|0)
  ];
}
